(1699001, 193854, 1040, 101330, 1072936800, '', 'Sweet!  Something besides CS:S!', '127.0.0.1', 1),
(1699009, 193854, 1040, 101566, 1072936800, '', 'hey guys is HL2DM released?', '127.0.0.1', 1),
(1699014, 193854, 1040, 101953, 1072936800, '', 'Excellent', '127.0.0.1', 1),
(1699015, 193854, 1040, 101410, 1072936800, '', 'omg thank you so much Valve, may God bless you', '127.0.0.1', 1),
